function renderDetalleDiarioUso(mes,marcas,sesiones,agregados){const dias=new Date(Number(mes.slice(0,4)),Number(mes.slice(5,7)),0).getDate(),filas=[];for(let dia=1;dia<=dias;dia++){const fecha=`${mes}-${String(dia).padStart(2,"0")}`,m=marcas.filter(x=>x.fecha===fecha),s=sesiones.filter(x=>x.fecha===fecha),a=agregados.filter(x=>x.registro===fecha),seg=s.reduce((t,x)=>t+segundosSesion(x),0),personas=new Set(m.map(x=>x.colaboradorId||x.colaboradorDocumento).filter(Boolean)).size,usado=m.length||s.length||a.length;filas.push(`<tr class="${usado?"day-used":"day-empty"}"><td><b>${new Date(`${fecha}T00:00:00`).toLocaleDateString("es-PE",{weekday:"short",day:"2-digit",month:"2-digit"})}</b></td><td>${s.length}</td><td>${s.length?h(tiempoUso(seg)):'<span class="no-history">Sin medición</span>'}</td><td>${m.length.toLocaleString("es-PE")}</td><td>${personas}</td><td>${a.length}</td></tr>`)}$("detalleDiarioUsoEmpresa").innerHTML=filas.join("")}
function renderEstadoColaboradores(activos,inactivos,desactivadosMes){const recientes=[...inactivos].sort((a,b)=>String(b.desactivacion).localeCompare(String(a.desactivacion))).slice(0,8);$("estadoColaboradoresEmpresa").innerHTML=`<div class="employee-state-summary"><article class="active"><b>${activos.length}</b><span>Activos</span></article><article class="inactive"><b>${inactivos.length}</b><span>Inactivos</span></article></div><h5>Desactivaciones${desactivadosMes.length?" del mes y recientes":" recientes"}</h5>${recientes.map(x=>`<div class="employee-state-row"><span><b>${h(x.datosPersonales?.nombres||x.nombre||x.id)}</b><small>${h(x.documento?.numero||x.dni||"")}</small></span><em>${x.desactivacion?h(fechaTexto(x.desactivacion)):"Fecha histórica no registrada"}</em></div>`).join("")||'<div class="usage-empty">No hay colaboradores inactivos.</div>'}`}
