$("modalPago").addEventListener("close",()=>{pagoEditandoId=null});
$("historialPagos").addEventListener("click",e=>{const editar=e.target.closest("[data-editar-pago]"),eliminar=e.target.closest("[data-eliminar-pago]");if(editar)abrirEdicionPago(editar.dataset.editarPago);if(eliminar)eliminarPago(eliminar.dataset.eliminarPago)});
document.addEventListener("click",e=>{const id=e.target.dataset.comprobante;if(!id)return;const p=datos?.pagos?.find(x=>x.id===id);if(!p?.archivoBase64)return;const bin=atob(p.archivoBase64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:p.archivoMime||"application/octet-stream"}));window.open(url,"_blank","noopener");setTimeout(()=>URL.revokeObjectURL(url),60000)});
function actualizarFiltroEmpresasAuditoria(){const select=$("filtroAuditoriaEmpresa"),actual=select.value;select.innerHTML='<option value="">Todas las empresas</option>'+empresas.map(e=>`<option value="${h(e.empresaId)}">${h(e.razonSocial)}</option>`).join("");select.value=actual}
function fechaAuditoria(valor){const d=valor?.toDate?.()||null;return d&&!Number.isNaN(d.getTime())?d:null}
function nombreEmpresaAuditoria(id){return empresas.find(e=>e.empresaId===id)?.razonSocial||id||"General"}
function etiquetaAccion(tipo){return String(tipo||"OPERACION").replaceAll("_"," ").toLowerCase().replace(/(^|\s)\S/g,c=>c.toUpperCase())}
function detalleAuditoria(r){if(r.motivo)return r.motivo;const omitir=new Set(["id","tipo","empresaId","fecha","superadminUid","superadminCorreo"]);return Object.entries(r).filter(([k,v])=>!omitir.has(k)&&v!==null&&v!==undefined&&typeof v!=="object").slice(0,5).map(([k,v])=>`${etiquetaAccion(k)}: ${v}`).join(" · ")||"Sin detalle adicional"}
async function cargarAuditoria(forzar=false){if(auditoriaCargada&&!forzar)return renderAuditoria();try{$("cuerpoAuditoria").innerHTML='<tr><td colspan="5">Cargando historial…</td></tr>';const s=await getDocs(query(collection(db,"auditoriaSuperadmin"),limit(1000)));registrosAuditoria=s.docs.map(x=>({id:x.id,...x.data()})).sort((a,b)=>(fechaAuditoria(b.fecha)?.getTime()||0)-(fechaAuditoria(a.fecha)?.getTime()||0));auditoriaCargada=true;const tipos=[...new Set(registrosAuditoria.map(r=>r.tipo).filter(Boolean))].sort();$("filtroAuditoriaTipo").innerHTML='<option value="">Todas las acciones</option>'+tipos.map(t=>`<option value="${h(t)}">${h(etiquetaAccion(t))}</option>`).join("");paginaAuditoria=1;renderAuditoria()}catch(x){toast(error(x),true);$("cuerpoAuditoria").innerHTML='<tr><td colspan="5">No se pudo cargar el historial.</td></tr>'}}
function auditoriaFiltrada(){const empresa=$("filtroAuditoriaEmpresa").value,tipo=$("filtroAuditoriaTipo").value,desde=$("filtroAuditoriaDesde").value,hasta=$("filtroAuditoriaHasta").value;return registrosAuditoria.filter(r=>{const iso=fechaAuditoria(r.fecha)?.toISOString().slice(0,10)||"";return(!empresa||r.empresaId===empresa)&&(!tipo||r.tipo===tipo)&&(!desde||iso>=desde)&&(!hasta||iso<=hasta)})}
function renderAuditoria(){const lista=auditoriaFiltrada(),paginas=Math.max(1,Math.ceil(lista.length/LIMITE_AUDITORIA));paginaAuditoria=Math.min(paginas,Math.max(1,paginaAuditoria));const inicio=(paginaAuditoria-1)*LIMITE_AUDITORIA,visibles=lista.slice(inicio,inicio+LIMITE_AUDITORIA);$("cuerpoAuditoria").innerHTML=visibles.map(r=>{const f=fechaAuditoria(r.fecha);return`<tr><td><b>${f?f.toLocaleDateString("es-PE"):"—"}</b><small>${f?f.toLocaleTimeString("es-PE",{hour:"2-digit",minute:"2-digit"}):""}</small></td><td>${h(nombreEmpresaAuditoria(r.empresaId))}</td><td><span class="audit-action">${h(etiquetaAccion(r.tipo))}</span></td><td>${h(detalleAuditoria(r))}</td><td>${h(r.superadminCorreo||"Superadministrador")}</td></tr>`}).join("")||'<tr><td colspan="5">No existen registros para los filtros seleccionados.</td></tr>';$("cantidadAuditoria").textContent=`${lista.length} registro${lista.length===1?"":"s"}`;$("paginaAuditoria").textContent=`Página ${paginaAuditoria} de ${paginas}`;$("auditoriaAnterior").disabled=paginaAuditoria<=1;$("auditoriaSiguiente").disabled=paginaAuditoria>=paginas}
["filtroAuditoriaEmpresa","filtroAuditoriaTipo","filtroAuditoriaDesde","filtroAuditoriaHasta"].forEach(id=>$(id).onchange=()=>{paginaAuditoria=1;renderAuditoria()});$("limpiarFiltrosAuditoria").onclick=()=>{["filtroAuditoriaEmpresa","filtroAuditoriaTipo","filtroAuditoriaDesde","filtroAuditoriaHasta"].forEach(id=>$(id).value="");paginaAuditoria=1;renderAuditoria()};$("auditoriaAnterior").onclick=()=>{paginaAuditoria--;renderAuditoria()};$("auditoriaSiguiente").onclick=()=>{paginaAuditoria++;renderAuditoria()};
$("exportarAuditoria").onclick=async()=>{const lista=auditoriaFiltrada();if(!lista.length)return toast("No hay registros para exportar.",true);const filas=lista.map(r=>({Fecha:fechaAuditoria(r.fecha)?.toLocaleString("es-PE")||"",Empresa:nombreEmpresaAuditoria(r.empresaId),Accion:etiquetaAccion(r.tipo),Detalle:detalleAuditoria(r),Responsable:r.superadminCorreo||"Superadministrador"}));try{const mod=await import("https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/+esm"),XLSX=mod.default||mod,libro=XLSX.utils.book_new(),hoja=XLSX.utils.json_to_sheet(filas);hoja["!cols"]=[{wch:20},{wch:32},{wch:28},{wch:65},{wch:34}];const rango=XLSX.utils.decode_range(hoja["!ref"]);for(let c=0;c<=rango.e.c;c++)hoja[XLSX.utils.encode_cell({r:0,c})].s={font:{bold:true,color:{rgb:"FFFFFF"}},fill:{fgColor:{rgb:"2867EE"}},alignment:{horizontal:"center"}};XLSX.utils.book_append_sheet(libro,hoja,"Historial");XLSX.writeFile(libro,`historial-administrativo-${isoLocal(new Date())}.xlsx`)}catch(x){toast("No se pudo generar el Excel: "+x.message,true)}};
async function auditoria(tipo,d={}){await setDoc(doc(collection(db,"auditoriaSuperadmin")),{tipo,...d,superadminUid:UID,superadminCorreo:EMAIL,fecha:serverTimestamp()});auditoriaCargada=false}function errorPassword(e){const codigo=String(e?.code||"").toLowerCase(),m=String(e?.message||"").replace(/^FirebaseError:\s*/,"");if(codigo.includes("not-found"))return"No se encontró esta cuenta en el acceso del sistema.";if(codigo.includes("permission-denied"))return"La cuenta seleccionada no es un administrador de esta empresa.";if(codigo.includes("unauthenticated"))return"Tu sesión de superadministrador venció. Vuelve a iniciar sesión.";if(codigo.includes("invalid-argument"))return m||"Revisa la contraseña y el motivo ingresados.";if(codigo.includes("internal")||/^internal$/i.test(m))return"El servidor no pudo completar el cambio. Verifica que las funciones actualizadas estén desplegadas y vuelve a intentarlo.";return m||"No se pudo cambiar la contraseña. Inténtalo nuevamente."}function error(e){const m=String(e?.message||"Error inesperado");return m.includes("permission")?"Las reglas gratuitas todavía no están publicadas o no autorizan esta operación.":m.replace(/^FirebaseError:\s*/,"")}function n(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim()}function h(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
